import{_ as i,o as e,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse(`{"title":"What's new with Crimson and Seastore?","description":"","frontmatter":{"title":"What's new with Crimson and Seastore?","date":"2022-11-10T00:00:00.000Z","updated":"2022-11-11T00:00:00.000Z","tags":["Ceph","Crimson","Seastore","Distributed Storage","Scalability"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/What_s_new_with_Crimson_and_Seastore.md","filePath":"posts/2022/What_s_new_with_Crimson_and_Seastore.md","lastUpdated":1780459816000}`),s={name:"posts/2022/What_s_new_with_Crimson_and_Seastore.md"};function o(l,a,n,_,h,m){return e(),t("div",null,[...a[0]||(a[0]=[r('<p>Ceph项目中的Crimson和Seastore是两个重要的研发方向，旨在提升Ceph存储系统的性能和可伸缩性。以下是会议内容的改进总结：</p><h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-crimson项目介绍及近期开发工作" tabindex="-1">会议主题：Crimson项目介绍及近期开发工作 <a class="header-anchor" href="#会议主题-crimson项目介绍及近期开发工作" aria-label="Permalink to &quot;会议主题：Crimson项目介绍及近期开发工作&quot;">​</a></h4><h4 id="主讲人-sam" tabindex="-1">主讲人：Sam <a class="header-anchor" href="#主讲人-sam" aria-label="Permalink to &quot;主讲人：Sam&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>Crimson项目概述</strong>：</p><ul><li>Crimson项目旨在减少每I/O的CPU开销，特别是针对新兴存储技术如NVMe。</li><li>项目重点在于优化CPU使用，提升每核心的IOPs，而非原始IOPs。</li></ul></li><li><p><strong>Crimson架构设计</strong>：</p><ul><li>通过预分配每个核心的单个线程和分区数据结构，避免核心切换，减少锁的使用。</li><li>使用C-star用户空间调度库，利用异步I/O结果，减少回调的使用。</li></ul></li><li><p><strong>C-store组件</strong>：</p><ul><li>C-store是针对Crimson的线程模型设计的对象存储实现，旨在避免CPU密集型元数据设计。</li><li>利用Zone Namespace Storage（ZNS）减少写放大和尾延迟。</li></ul></li><li><p><strong>近期开发工作</strong>：</p><ul><li>稳定化Blue Store RBD RADOS测试，实现多核心数据结构分区和消息路由架构。</li><li>快照支持：基本I/O路径组件已实现，修剪和恢复组件正在进行中。</li><li>用户保护措施：添加实验性功能标志，防止用户意外创建Crimson OSDs。</li></ul></li><li><p><strong>下一步计划</strong>：</p><ul><li>扩展测试覆盖范围，实现scrub功能，提升正确性验证。</li><li>多核心支持的进一步改进，包括多反应器支持和性能测试。</li><li>C-store的稳定性提升，包括多核心反应器支持和快照功能的实现。</li></ul></li><li><p><strong>问答环节</strong>：</p><ul><li>建议使用vstart命令和Crimson标志进行部署。</li><li>Crimson未来将支持EC（Erasure Coding），但具体时间取决于后续工作进展。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续推进Crimson和Seastore的开发，特别是在多核心支持和性能优化方面。</li><li>完善文档和测试，确保Crimson和Seastore能够安全地用于特定生产环境中。</li><li>定期发布性能测试数据，以便社区了解Crimson和Seastore的进展和性能表现。</li></ul>',8)])])}const u=i(s,[["render",o]]);export{p as __pageData,u as default};
